#nullable enable
using System.Collections.Generic;
using System.Linq;
using JetBrains.ReSharper.Psi;
using Newtonsoft.Json;

namespace DotNetAnalysisAndRefactoringMcp.Tools.Json;

/// <summary>
///   A type's member in the <see cref="JsonFormat">JSON form</see>, as <see cref="MemberListing"/> lists it: declared
///   in the type, not inherited, nor generated by the compiler. A C# 14 extension block is one too, of kind
///   <c>extension</c>, with its receiver and its own members.
/// </summary>
public sealed class MemberJson
{
   /// <summary>"public" and the like, as C# writes it; left out when C# writes none, as for an explicit interface implementation.</summary>
   [JsonProperty("access", NullValueHandling = NullValueHandling.Ignore)] public string? Access { get; private set; }

   [JsonProperty("kind")] public string Kind { get; private set; } = "";

   /// <summary>
   ///   The bare C# identifier: an explicit interface implementation's is the member's, with the interface in
   ///   <see cref="ExplicitInterface"/>. Left out for an extension block, which has none.
   /// </summary>
   [JsonProperty("name", NullValueHandling = NullValueHandling.Ignore)] public string? Name { get; private set; }

   [JsonProperty("signature")] public string Signature { get; private set; } = "";

   /// <summary>The interface an explicit interface implementation implements, as C# writes it, such as <c>IDisposable</c>.</summary>
   [JsonProperty("explicitInterface", NullValueHandling = NullValueHandling.Ignore)] public string? ExplicitInterface { get; private set; }

   /// <summary>An extension block's receiver.</summary>
   [JsonProperty("receiver", NullValueHandling = NullValueHandling.Ignore)] public ReceiverJson? Receiver { get; private set; }

   /// <summary>An extension block's members.</summary>
   [JsonProperty("members", NullValueHandling = NullValueHandling.Ignore)] public List<MemberJson>? Members { get; private set; }

   static MemberJson Of(ITypeMember member)
   {
      var implemented = (member as IOverridableMember)?.ExplicitImplementations.FirstOrDefault();
      var block = member as ITypeExtension;
      return new MemberJson
             {
                Access = block == null && implemented == null ? MemberListing.AccessOf(member) : null,
                Kind = JsonNaming.KindOf(member),
                Name = block == null ? implemented?.MemberName ?? JsonNaming.NameOf(member) : null,
                Signature = DotNetAnalysisAndRefactoringMcp.Signature.Of(member),
                ExplicitInterface = implemented?.DeclaringType.GetPresentableName(member.PresentationLanguage),
                Receiver = block == null ? null : ReceiverJson.Of(block),
                Members = block == null ? null : [.. new MemberListing(block).Members.Select(Of)]
             };
   }

   /// <summary>The members of <paramref name="type"/> that are not types: its nested types are <see cref="TypeJson.NestedTypes"/>.</summary>
   public static List<MemberJson> OfTheMembersOf(ITypeElement type) =>
      [.. new MemberListing(type).Members.Where(it => it is ITypeExtension or not ITypeElement).Select(Of)];
}
